import sys, re
from pathlib import Path

baseFolder = Path(__file__).parent.parent

DATA_FOLDER = f'{baseFolder}/out/battery20240813_sro_demo_siggen'  # folder path valid as of 2024/08/14 (not yet moved to an external hard-drive to save space)

def main(dataFolder=DATA_FOLDER):
    """Main function (called by default when running script)."""
    data = get_data(dataFolder)


def get_data(dataFolder: str):
    """Get data from the data folder."""
    # List all subfolders
    subfolders = [f for f in Path(dataFolder).iterdir() if f.is_dir()]
    # Get parameters ranges from subfolders names
    paramsRanges = get_param_ranges(subfolders)


def get_param_ranges(subfolders: list):
    """Get parameters ranges from subfolders names."""
    # Get all parameters
    allParams = [f.name.split('_') for f in subfolders]
    # Get all parameters ranges
    paramsRanges = {}
    for paramSet in allParams:
        for param in paramSet:
            # Extract numeric value in string
            idx = -1
            while re.match(r'\d', param[idx]):
                idx -= 1
            # Get parameter name
            paramName = param[:idx+1]
            # Get parameter value
            paramValue = int(param[idx+1:])
            if paramName in paramsRanges.keys():
                if paramValue not in paramsRanges[paramName]:
                    paramsRanges[paramName].append(paramValue)
            else:
                paramsRanges[paramName] = [paramValue]
    # Sort parameter values
    for paramName in paramsRanges.keys():
        paramsRanges[paramName] = sorted(paramsRanges[paramName])
    return paramsRanges


if __name__ == '__main__':
    sys.exit(main())